import { createPlayerError } from "../../core/errors.js";

/** Returns true when Picture-in-Picture is available. */
export function canPictureInPicture(): boolean {
  return (
    typeof document !== "undefined" &&
    "pictureInPictureEnabled" in document &&
    document.pictureInPictureEnabled === true
  );
}

/** Requests Picture-in-Picture for a video element. */
export async function requestPictureInPicture(media: HTMLVideoElement): Promise<void> {
  if (typeof media.requestPictureInPicture !== "function") {
    throw createPlayerError("Picture-in-Picture is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  await media.requestPictureInPicture();
}

/** Exits Picture-in-Picture when active. */
export async function exitPictureInPicture(): Promise<void> {
  if (typeof document === "undefined" || typeof document.exitPictureInPicture !== "function") {
    throw createPlayerError("Picture-in-Picture is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  if (document.pictureInPictureElement !== null) {
    await document.exitPictureInPicture();
  }
}
